{
  "A_valid": "无效。A属于套取金融机构贷款转贷，乙不知资金来源及利率仅为6%均不改变该结论。",
  "A_restitution": "122828.00",
  "A_guarantee": "保证合同无效。丁不承担本案请求的保证给付责任，不应立即支付；无效保证的过错赔偿不在本案请求范围。",
  "B_initial_principal": "186290.00",
  "B_protected_total": "202317.84",
  "B_guarantee": "戊的连带责任保证有效且责任存续，覆盖B全部未偿受保护本息202317.84元，甲可请求其立即支付。内部50%分担约定不限制其对甲的责任，亦不存在因庚保证责任消灭而减责的情形。",
  "C_outstanding_principal": "151539.07",
  "C_outstanding_interest": "1403.29",
  "C_outstanding_expenses": "0.00",
  "C_guarantee": "己构成有效且责任存续的一般保证，覆盖C全部剩余债务152942.36元。己享有先诉抗辩，本次请求其立即支付不应支持，当前立即支付额为0.00元；辛加入债务不使己免责，也不消除该抗辩。",
  "borrower_total": "478088.20",
  "B_second_guarantee": "庚的连带责任保证有效且责任存续，甲已在保证期间内向其独立行权。庚对B全部剩余202317.84元承担保证责任，可被请求立即支付，其不再承担保证责任的主张不成立。",
  "B_joint_payment_limit": "202317.84",
  "C_third_party_type": "部分债务加入，即并存的债务承担。辛在SP-01结算后C余额的50%范围内与乙承担连带债务，并非保证或免责债务转移。",
  "C_third_party_payment_limit": "76471.18",
  "basis": {
    "A效力与返还": {
      "facts": ["S01", "S02", "S12"],
      "rules": [
        "lending-2020-12第13条、第31条",
        "civil-code-2020第157条、第682条"
      ],
      "explanation": "A成立于2022年，适用现行套取金融机构贷款转贷即无效的规则，不以高利或借款人预先知情为要件，不能套用lending-2015第14条的旧条件。实际交付143089.00元，已返20261.00元依双方协议全部冲抵返还债务，剩余143089.00－20261.00＝122828.00元，由乙立即返还。未交付票面差额不计入；同交易号收据不构成第二次交付。主合同无效导致丁的保证合同无效，本案不审查未请求的过错赔偿。"
    },
    "B本金与本息计算": {
      "facts": ["S03", "S04", "S05", "S06", "S13"],
      "rules": [
        "civil-code-2020第670条、第679条、第680条",
        "lending-2020-12第25条至第28条"
      ],
      "explanation": "B为合法自有资金借款。预扣利息12493.00元不得作为本金，最初本金为198783.00－12493.00＝186290.00元。三次换据均无新增交付且不是债务更新，应从实际本金重算合法结息，不能直接接受纸面本金。合同年利率13.2%低于成立时LPR四倍14.8%；逾期部分依第28条仍按13.2%计算。",
      "calculation": "相邻结算区间日数依次为175、103、84、204日，合计566日。逐次结息额＝186290×(1＋0.132×175/365)×(1＋0.132×103/365)×(1＋0.132×84/365)×(1＋0.132×204/365)＝227317.837835元。全程总量上限＝186290×(1＋0.148×566/365)＝229043.810192元。取两者较低值，再扣SP-01的25000.00元，最终B余额为202317.84元。计算过程中不先取分。"
    },
    "B两名保证人": {
      "facts": ["S06", "S12"],
      "rules": [
        "civil-code-2020第688条、第691条至第693条、第695条",
        "guarantee-2020第13条、第25条、第29条、第31条、第32条、第34条"
      ],
      "explanation": "戊的无条件清偿、无须先向乙追索条款属于连带责任保证，且共同正文明确戊、庚各自覆盖全部B债务。保证至本息还清的期间条款属于约定不明，依法为六个月；两人未书面同意展期，保证期间仍按原到期日2023-01-12计算，至2023-07-12届满。对戊的诉状于07-07送达，虽07-09撤诉，仍构成期间内行权；对庚的完整请求于07-06独立到达，也在期间内。不能把向戊行权自动视为向庚行权，但本案已有对庚的独立及时请求。两人的责任均存续，07-18催告不是挽救保证责任的依据。内部相互追偿及各50%分担有效，但不改变对外各自全额保证；庚未因逾期行权而免责，戊关于丧失追偿权减责的事实前提不存在。"
    },
    "SP01抵充顺序": {
      "facts": ["S06", "S10", "S13", "S14"],
      "rules": [
        "civil-code-2020第560条、第561条、第687条、第693条",
        "guarantee-2020第31条"
      ],
      "explanation": "09:20到账的25000.00元依双方约定只能清偿B、C，不得冲抵A。付款时B、C均已到期，戊、庚及己的全额保证均存续且履行能力充足；己享有先诉抗辩不等于C没有有效保证。S13附件约定的比较条件成立，应比较依法可强制请求的年利率：B为13.2%，C为13%，故全部先抵B，不能拿C名义23.5%比较。13:40成立的辛债务加入以SP-01结算后的C余额为范围，没有追溯变更抵充的约定，乙要求重新抵充的主张不成立。"
    },
    "C利率与付款认定": {
      "facts": ["S07", "S08", "S09", "S11", "S13", "S14"],
      "rules": [
        "lending-2015第26条",
        "lending-2020-12第25条、第28条、第31条",
        "civil-code-2020第560条、第561条"
      ],
      "explanation": "C于2019-02-07成立，甲明确请求适用分段规则：截至2020-08-19的利息按约定23.5%计算，未超过旧规则24%；2020-08-20起按起诉时LPR四倍即13%计算，包括逾期阶段。2022年保证和2023年代偿支持均不构成新借款或债务更新。按未偿本金、实际日数/365单利计算，不对欠息计息。2019年双方原协议确定费用、合法利息、本金的顺序，T-02另有双方有效协议，改为本金优先；其他付款中的乙单方本金备注不能改变顺序。S08指定C仅解决清偿哪笔债务的问题。T-01的截图、收据与主表是同一交易，只计一次；X-01未执行、未到账，不产生清偿效果，乙关于点击提交即已付款的主张不成立。"
    },
    "C计算核对": {
      "facts": ["S07", "S08", "S09", "S11", "S13"],
      "calculation": "相邻节点为：2019-02-07、T-01、T-02、T-03、2020-08-20、T-04、T-05、T-06、T-07、2023-08-01；区间日数依次为70、127、175、188、32、202、421、395、26日。前四段按23.5%，后五段按13%。每段利息＝该段未偿本金×适用年利率×日数/365；各次付款按有效约定抵充。",
      "ledger": [
        "T-01先付费用1680.00元及利息10229.195890元，付款后本金213658.195890元，费用和利息均清零。",
        "T-02的26952.00元全部偿本金，付款后本金186706.195890元，利息17470.216045元未清偿。",
        "T-03付款不足清偿累计利息，本金仍为186706.195890元，余息9823.633321元。",
        "T-04经新旧利率分段后付款仍不足清偿利息，本金仍为186706.195890元，余息4136.694991元。",
        "T-05付清累计利息并偿部分本金，剩余本金172130.506509元；T-06后本金164064.650677元；T-07后本金151539.074820元，各次付款后欠息均为零。",
        "末段利息＝151539.074820359…×13%×26/365＝1403.293350元。SP-01全部抵B，C不另扣款；S14没有新增付款。"
      ],
      "rounding": "上述中间展示不作为逐期取分依据。最终本金151539.07元、利息1403.29元、费用0.00元分别取分后合计152942.36元，不将未取分的本息先合计取分。"
    },
    "C一般保证": {
      "facts": ["S07", "S10", "S12", "S14"],
      "rules": [
        "civil-code-2020第1260条、第686条、第687条、第691条至第693条、第697条",
        "guarantee-2020第25条、第31条、第34条"
      ],
      "explanation": "己的保证成立于2022年，应适用当时保证规则，不能因主借款成立于2019年改用旧规则。不能履行、无力偿还时才代偿的正文构成一般保证。未约定保证期间，期间自2022-12-15主债务到期起算六个月，至2023-06-15届满。05-08仅向己催告不足以完成一般保证行权；06-08起诉后虽撤诉，甲已在06-14即期间届满前重新起诉乙，因此保证责任存续。06-25仅确认收件且明确不确认付款义务，不是新保证，也不是放弃先诉抗辩，本案无须靠该签收恢复责任。案件尚未审判、没有执行受偿，乙有财产且无先诉抗辩例外，故己现在有权拒绝支付，而非保证责任已经消灭。"
    },
    "辛的义务与单方主张": {
      "facts": ["S12", "S14"],
      "rules": [
        "civil-code-2020第552条、第697条",
        "guarantee-2020第36条"
      ],
      "explanation": "代偿支持正文明确辛与乙一并负担债务，甲可单独向辛请求且不以先追索、执行或乙无力偿还为条件，并不免除乙，故属于部分债务加入，不适用性质难明时认定为保证的分支，也不是债务转移。甲已获准追加辛并提出相应给付请求，C已到期，辛在承诺范围内应立即支付。甲所称无论正文如何均应立即支付的理由不成立；本案支持立即给付源于正文中的债务加入，而非文件标题。加入不增加C债权总额，也不改变己原有保证责任。",
      "calculation": "承诺基数＝151539.07＋1403.29＋0.00＝152942.36元；辛承担50%，即76471.18元，其余为152942.36－76471.18＝76471.18元。乙仍负担全部C债务。"
    },
    "最终总额与责任重合": {
      "facts": ["S02", "S06", "S07", "S12", "S13", "S14"],
      "rules": [
        "civil-code-2020第157条、第552条、第687条、第688条、第697条"
      ],
      "explanation": "乙作为A返还义务人、B和C借款人，应立即支付全部剩余实体债务。借款人总额＝122828.00＋202317.84＋151539.07＋1403.29＋0.00＝478088.20元。戊、庚的B保证责任与乙的同一B债务重合，甲对B累计受偿不得超过202317.84元，不能将两名保证人的各自限额相加为额外债权。辛在76471.18元内与乙负连带债务，己仅在一般保证条件成就后的未清偿范围负责；这些责任均不重复计入乙的总额，任何实际清偿均相应减少同一债权及其他责任人的重合责任范围。"
    }
  }
}
